from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(15,'constructions','Programmes de construction','4 · Espace et géométrie',
'Perpendiculaires · Parallèles · Cercles · Programmes',
['Tracer perpendiculaires, parallèles et cercles avec précision.','Exécuter un programme de construction pas à pas.','Élaborer un programme de construction dans des cas simples.'],
['Instruments et vocabulaire du CM1.'],[
page(1,'Les tracés de référence',
bloc('definition',r'Deux droites perpendiculaires se coupent en angle droit, vérifié à l’équerre ; deux droites parallèles gardent un écart constant et ne se coupent jamais. Le cercle de centre O et de rayon 3 cm réunit tous les points situés à exactement 3 cm de O.'),
bloc('savoirfaire',r'Perpendiculaire passant par un point : un côté de l’angle droit de l’équerre sur la droite, glisser jusqu’au point, tracer. Parallèle : l’équerre appuyée sur la droite, une règle contre l’équerre, glisser, tracer.','Équerre et règle ensemble'),
bloc('exemple',r'Un diamètre vaut deux rayons : un cercle de rayon $3{,}5$ cm a des diamètres de 7 cm. Le compas reporte aussi les longueurs : il transporte un écartement sans le mesurer.'),
bloc('attention',r'Les codes écrivent les propriétés sur la figure : petit carré pour l’angle droit, traits identiques pour les longueurs égales. Une figure sans codes ne garantit rien.')),
page(2,'Écrire un programme de construction',
bloc('definition',r'Un programme de construction est une suite d’instructions qui permet de reproduire une figure sans la voir. Chaque phrase nomme les points et les objets : « Trace le segment [AB] de 5 cm. », « Trace le cercle de centre A passant par B. »'),
bloc('savoirfaire',r'Pour élaborer un programme : faire un croquis codé ; choisir l’ordre des tracés (par quoi faut-il commencer ?) ; nommer les points au fur et à mesure ; relire en imaginant quelqu’un qui ne voit pas la figure.','Élaborer pas à pas'),
bloc('exemple',r'Programme du carré ABCD de côté 4 cm : tracer [AB] de 4 cm ; tracer la perpendiculaire à (AB) en A et y reporter AD $=4$ cm ; tracer la perpendiculaire à (AB) en B et y reporter BC $=4$ cm ; joindre D à C. Contrôler le dernier angle.'),
bloc('attention',r'L’ordre des étapes compte : on ne peut pas tracer « le cercle de centre O passant par A » avant d’avoir placé O et A. Un bon programme s’exécute sans retour en arrière.'))
],[
E('Les bons mots',r'Sur la figure, nommer avec la bonne notation : le segment joignant R et S ; la droite passant par T et U ; la longueur du segment [RS].',r'Le segment $\res{[RS]}$, la droite $\res{(TU)}$ et la longueur $\res{RS}$, sans crochets : trois écritures pour trois objets.','Associer chaque notation à son objet.','assert 1==1',figure='geo-1'),
E('Tracer une perpendiculaire',r'Tracer la perpendiculaire à la droite (d) passant par le point M.',r'L’équerre glisse le long de (d) jusqu’à M ; le tracé vert coupe (d) à angle droit codé.','Garder un côté de l’équerre sur la droite.','assert 1==1',figure='geo-2'),
E('Tracer une parallèle',r'Tracer la parallèle à la droite (d) passant par le point N.',r'L’équerre s’appuie sur (d), la règle tient l’équerre, on glisse jusqu’à N : la parallèle verte garde le même écart.','Bloquer la règle, faire glisser l’équerre.','assert 1==1',figure='geo-3'),
E('Rayon et diamètre',r'Un cercle a un rayon de $3{,}5$ cm. Que mesure un diamètre ? Si un cercle a un diamètre de 9 cm, que mesure son rayon ?',r'Diamètre : $3{,}5\times2=\res7$ cm. Rayon : $9:2=\res{4{,}5}$ cm.','Le diamètre vaut deux rayons.','assert Rational("3.5")*2==7 and Rational(9,2)==Rational("4.5")',figure='geo-4'),
E('Exécuter un programme',r'Exécuter : trace un rectangle ABCD avec AB $=5$ cm et BC $=3$ cm ; place le milieu M de [AB] ; trace le cercle de centre M passant par A.',r'Le rectangle se construit à l’équerre ; M est à $2{,}5$ cm de A ; le cercle de centre M passant par A a un rayon de $\res{2{,}5}$ cm et passe aussi par B. La construction figure en vert.','Suivre les étapes dans l’ordre écrit.','assert Rational(5,2)==Rational("2.5")',figure='geo-5'),
E('Le triangle du compas',r'Exécuter : trace [EF] de 5 cm ; trace l’arc de cercle de centre E et de rayon 4 cm ; trace l’arc de centre F et de rayon 4 cm ; nomme G leur point d’intersection ; trace le triangle EFG. Quelle est la nature du triangle ?',r'Les deux arcs de même rayon donnent GE $=$ GF $=4$ cm : le triangle est $\res{\text{isocèle}}$ en G. La construction verte garde les arcs visibles.','Relire la définition du cercle pour conclure.','assert 4==4 and 4+4>5',figure='geo-6'),
E('Le programme en désordre',r'Remettre en ordre les instructions du programme du cercle circonscrit au carré : (a) trace le cercle de centre O passant par A ; (b) trace le carré ABCD de côté 4 cm ; (c) trace les diagonales [AC] et [BD] ; (d) nomme O leur point d’intersection.',r'L’ordre est $\res{\text{b, c, d, a}}$ : impossible de tracer le cercle de centre O avant d’avoir obtenu O. Chaque étape utilise les objets déjà construits.','Chercher ce dont chaque phrase a besoin.','assert 1==1',figure='geo-7'),
E('L’étape impossible',r'Un programme dit : « 1. Trace le cercle de centre O et de rayon 3 cm. 2. Place un point P à 5 cm de O. 3. Le point P est sur le cercle. » Quelle phrase est fausse ? Corriger.',r'La phrase 3 : un point du cercle est à exactement $\res{3\ \mathrm{cm}}$ de O, or P est à 5 cm, donc P est $\res{\text{à l’extérieur}}$ du cercle. On corrige : « P est à l’extérieur du cercle. »','Confronter chaque phrase à la définition du cercle.','assert 5>3',figure='geo-8'),
E('Écrire le programme',r'Écrire un programme de construction pour la figure dessinée : un carré RSTU de côté 3 cm et sa diagonale [RT].',r'Un programme correct : trace [RS] de 3 cm ; trace la perpendiculaire à (RS) en R et place U à 3 cm de R ; trace la perpendiculaire à (RS) en S et place T à 3 cm de S ; joins U à T ; trace le segment [RT]. D’autres ordres corrects existent : l’essentiel est de ne rien utiliser avant de l’avoir construit.','Nommer les points et donner les mesures.','assert 3==3',figure='geo-9'),
E('Le cercle bien défini',r'Écrire un programme en deux instructions qui construit un cercle passant par un point A donné, de centre un point O donné. Quelle longueur faut-il reporter au compas ?',r'Programme : pointe du compas en O, ouverture jusqu’à A ; tracer le cercle. Le rayon reporté est la longueur $\res{OA}$ : le cercle passe alors exactement par A.','Définir le rayon par les deux points donnés.','assert 1==1',figure='geo-10'),
E('La figure au téléphone',r'Léna dicte à Max : « Trace un losange LMNO de 4 cm de côté. » Max répond : « Il me manque une information pour que nos figures soient superposables. » Qui a raison ? Expliquer.',r'$\res{\text{Max a raison}}$ : tous les losanges de côté 4 cm ne sont pas superposables, leur ouverture d’angle peut changer. Il faut ajouter une donnée, par exemple la longueur d’une diagonale ou un angle à décalquer.','Chercher deux figures différentes qui respectent la consigne.','assert 4==4',figure='geo-11'),
E('Les cercles concentriques',r'Exécuter : place un point O ; trace les cercles de centre O et de rayons 1 cm, 2 cm et 3 cm. Quelle est la largeur de chaque anneau obtenu ?',r'Les trois cercles partagent le même centre : des cercles concentriques. Chaque anneau a une largeur de $2-1=\res1$ cm, puis $3-2=\res1$ cm : des anneaux réguliers.','Soustraire les rayons voisins.','assert 2-1==1 and 3-2==1',figure='geo-12'),
E('La cible du stand',r'Une cible est formée de trois cercles concentriques de rayons 2 cm, 4 cm et 6 cm. Écrire le programme de construction, puis donner le diamètre du grand cercle.',r'Programme : place un point O ; trace le cercle de centre O et de rayon 2 cm ; puis de rayon 4 cm ; puis de rayon 6 cm. Le grand diamètre vaut $6\times2=\res{12}$ cm.','Garder le même centre à chaque étape.','assert 6*2==12',figure='geo-13'),
E('La maison à construire',r'Exécuter : trace un carré ABCD de côté 4 cm, le côté [DC] en haut ; place le milieu M du segment [DC] ; trace la perpendiculaire à (DC) passant par M et place le point T à 2 cm au-dessus de M ; trace les segments [DT] et [CT]. Quelle figure obtient-on ?',r'Le carré coiffé du triangle isocèle DTC dessine $\res{\text{une maison}}$ : le toit a son sommet T au-dessus du milieu M, donc DT $=$ CT. La construction figure en vert.','Construire le carré avant le toit.','assert 4//2==2',figure='geo-14'),
E('L’ordre qui compte',r'Vrai ou faux : « Dans un programme de construction, on peut toujours échanger deux instructions sans changer la figure. » Justifier avec un exemple.',r'$\res{\text{Faux}}$ : « place le milieu M de [AB] » doit suivre le tracé de [AB] ; échangées, les instructions deviennent inexécutables. Certaines étapes indépendantes peuvent s’échanger, mais pas celles qui utilisent un objet encore absent.','Chercher une instruction qui dépend d’une autre.','assert 1==1',figure='geo-15')
],reperes=['Tracés aux instruments','Cercle et distances','Exécuter un programme','Élaborer et corriger un programme'],deco='geometrie')

chapitre(16,'polygones','Polygones, du triangle à l’hexagone','4 · Espace et géométrie',
'Triangles · Quadrilatères · Trapèzes · Pentagones · Hexagones',
['Reconnaître et nommer les polygones jusqu’à l’hexagone.','Utiliser les propriétés des figures usuelles, trapèzes compris.','Construire ces figures et justifier avec les instruments.'],
['Constructions du chapitre 15.'],[
page(1,'Les triangles, bien en main',
bloc('definition',r'Un polygone est une figure fermée dont les côtés sont des segments. Trois côtés : triangle ; quatre : quadrilatère ; cinq : pentagone ; six : hexagone. Le triangle rectangle a un angle droit, l’isocèle deux côtés égaux, l’équilatéral trois.'),
r'@FIG:cours-triangles@',
bloc('propriete',r'Dans un triangle isocèle, les angles à la base sont égaux ; dans un équilatéral, les trois angles sont égaux. Les codes affirment ces propriétés sur la figure.'),
bloc('savoirfaire',r'Construire au compas : pour un isocèle de base 4 cm et de côtés 6 cm, tracer la base, puis deux arcs de rayon 6 cm centrés aux extrémités ; leur croisement donne le sommet principal.','Le compas reporte les côtés')),
page(2,'Quadrilatères et trapèzes',
bloc('definition',r'Le rectangle a quatre angles droits ; le losange, quatre côtés égaux ; le carré, les deux. Le trapèze a deux côtés opposés parallèles ; le trapèze rectangle possède en plus deux angles droits.'),
r'@FIG:cours-trapeze@',
bloc('propriete',r'Dans le rectangle, le losange et le carré, les côtés opposés sont parallèles deux à deux. Dans le trapèze, seule la paire de côtés parallèles est garantie : les deux autres côtés peuvent être quelconques.'),
bloc('attention',r'Un carré est à la fois un rectangle et un losange : il en possède toutes les propriétés. Une figure peut porter plusieurs noms ; le plus précis est le plus informatif.')),
page(3,'Pentagones et hexagones',
bloc('definition',r'Un pentagone a 5 côtés et 5 sommets ; un hexagone, 6 côtés et 6 sommets. Un polygone est régulier quand tous ses côtés et tous ses angles sont égaux : l’hexagone des alvéoles d’abeilles est régulier.'),
r'@FIG:cours-hexagone@',
bloc('savoirfaire',r'Construire un hexagone régulier : tracer un cercle ; garder la même ouverture de compas (le rayon) et la reporter six fois sur le cercle ; joindre les six points. Le tour de cercle se ferme exactement.','L’hexagone au compas'),
bloc('exemple',r'Le côté de cet hexagone régulier est égal au rayon du cercle : un hexagone construit dans un cercle de rayon 4 cm a des côtés de 4 cm et un périmètre de 24 cm.')),
page(4,'Construire et justifier',
bloc('savoirfaire',r'Avant de nommer une figure, vérifier ses propriétés aux instruments : équerre pour les angles droits, compas ou règle graduée pour les longueurs, règle et équerre pour le parallélisme. L’allure ne suffit jamais.','Les instruments tranchent'),
bloc('exemple',r'Un trapèze rectangle de bases 6 cm et 4 cm et de hauteur 3 cm se construit comme un rectangle auquel on incline un côté : tracer la base, deux perpendiculaires, reporter 6 cm et 4 cm, joindre.'),
bloc('propriete',r'Une figure composée se décompose en figures simples : un trapèze rectangle se découpe en un rectangle et un triangle rectangle. Ce découpage sert pour les contours, les aires et les programmes de construction.'),
bloc('attention',r'Les diagonales du rectangle ont la même longueur et se coupent en leur milieu : cette observation, vérifiée à la règle, contrôle efficacement une construction.'))
],[
E('Compter les côtés',r'Nommer chacun des quatre polygones dessinés : triangle, quadrilatère, pentagone ou hexagone.',r'Trois côtés : $\res{\text{triangle}}$ ; quatre : $\res{\text{quadrilatère}}$ ; cinq : $\res{\text{pentagone}}$ ; six : $\res{\text{hexagone}}$. On compte les côtés ou les sommets.','Compter côtés ou sommets.','assert 3<4<5<6',figure='tri-1'),
E('Classer les triangles',r'Classer les quatre triangles dessinés : rectangle, isocèle, équilatéral ou quelconque, en lisant les codes.',r'Le petit carré signale le $\res{\text{rectangle}}$ ; deux traits identiques, l’$\res{\text{isocèle}}$ ; trois, l’$\res{\text{équilatéral}}$ ; aucun code : $\res{\text{quelconque}}$.','Lire les codes avant l’allure.','assert 1==1',figure='tri-2'),
E('L’isocèle au compas',r'Construire un triangle isocèle de base 4 cm et de côtés égaux de 6 cm. Garder les arcs.',r'Deux arcs de rayon 6 cm centrés aux extrémités de la base se croisent au sommet principal. Les codes verts affirment les côtés égaux.','Même ouverture de compas pour les deux arcs.','assert 6+6>4',figure='tri-3'),
E('Trapèze ou pas ?',r'Parmi les quatre quadrilatères dessinés, lesquels sont des trapèzes ? Justifier avec le parallélisme.',r'Les figures 1 et 3 ont deux côtés opposés $\res{\text{parallèles}}$ : des trapèzes ; la figure 1, avec ses deux angles droits codés, est un trapèze $\res{\text{rectangle}}$. Les figures 2 et 4 n’ont aucune paire de côtés parallèles.','Contrôler l’écart constant entre côtés opposés.','assert 2<=4',figure='tri-4'),
E('La carte d’identité',r'Pour le trapèze rectangle dessiné : combien d’angles droits ? Quels côtés sont parallèles ?',r'Il porte $\res2$ angles droits, posés sur le même côté. Les côtés parallèles sont les deux $\res{\text{bases}}$, la grande et la petite ; les deux autres côtés ne le sont pas.','Lire les codes de la figure.','assert 2==2',figure='tri-5'),
E('Le rectangle contrôlé',r'Construire un rectangle de 7 cm sur 4 cm, tracer ses diagonales et les mesurer. Que constate-t-on ?',r'Les deux diagonales mesurent chacune environ $\res{8{,}1}$ cm : elles ont la $\res{\text{même longueur}}$ et se coupent en leur milieu. Ce double contrôle valide la construction.','Mesurer les deux diagonales.','assert 7*7+4*4==65',figure='tri-6'),
E('Le carré incliné',r'Construire un carré de côté 5 cm dont un côté est déjà tracé en biais. L’orientation change-t-elle la nature de la figure ?',r'$\res{\text{Non}}$ : perpendiculaires aux extrémités, report de 5 cm, jonction : le carré reste un carré, quelle que soit son inclinaison sur la feuille.','S’appuyer sur le côté donné.','assert 5*4==20',figure='tri-7'),
E('Le losange au compas',r'Construire un losange de côté 4 cm à partir de l’angle donné au croquis, au compas seulement.',r'Depuis le sommet, reporter 4 cm sur chaque côté de l’angle, puis croiser deux arcs de rayon 4 cm pour fermer la figure : quatre côtés égaux, codés en vert.','Même ouverture du compas pour les quatre côtés.','assert 4*4==16',figure='tri-8'),
E('L’hexagone régulier',r'Construire un hexagone régulier dans un cercle de rayon 4 cm, en reportant le rayon au compas. Donner son périmètre.',r'Le rayon reporté six fois sur le cercle donne les six sommets : chaque côté vaut le rayon, 4 cm. Périmètre : $6\times4=\res{24}$ cm. La construction verte garde les arcs.','Ne jamais changer l’ouverture du compas.','assert 6*4==24',figure='tri-9'),
E('Régulier ou non ?',r'Deux pentagones sont dessinés : lequel est régulier ? Justifier.',r'Le premier a cinq côtés codés égaux et des angles tous pareils : $\res{\text{régulier}}$. Le second a des côtés visiblement inégaux : irrégulier. Le nom « pentagone » dit le nombre de côtés, pas leur égalité.','Vérifier côtés et angles, pas l’allure.','assert 5==5',figure='tri-10'),
E('Le trapèze décomposé',r'Montrer que le trapèze rectangle dessiné (bases 6 cm et 4 cm, hauteur 3 cm) se découpe en un rectangle et un triangle rectangle. Donner les dimensions de chacun.',r'La perpendiculaire issue du sommet de la petite base découpe un rectangle de $\res{4\times3}$ cm et un triangle rectangle de côtés de l’angle droit $\res{2}$ cm ($6-4$) et $\res3$ cm. Le découpage figure en vert.','Abaisser une perpendiculaire depuis la petite base.','assert 6-4==2',figure='tri-11'),
E('Le programme de l’hexagone',r'Écrire un programme de construction de l’hexagone régulier de côté 3 cm.',r'Programme : trace un cercle de centre O et de rayon 3 cm ; choisis un point A sur le cercle ; sans changer l’ouverture du compas, reporte le rayon six fois autour du cercle à partir de A ; joins les six points voisins. Le périmètre obtenu vaut $6\times3=\res{18}$ cm.','Utiliser l’égalité côté = rayon.','assert 6*3==18',figure='tri-12'),
E('La table basse',r'Le plateau d’une table a la forme d’un trapèze : bases de 90 cm et 60 cm, deux autres côtés de 40 cm chacun. Calculer la longueur de la baguette de chant qui fait tout le tour.',r'Le tour additionne les quatre côtés : $90+60+40+40=\res{230}$ cm, soit $2{,}30$ m.','Additionner tous les côtés du contour.','assert 90+60+40+40==230',figure='tri-13'),
E('Les alvéoles',r'Les abeilles pavent leurs rayons d’hexagones réguliers. Combien de côtés chaque alvéole partage-t-elle avec ses voisines quand elle est entourée de toutes parts ? Quel est l’intérêt de ce partage ?',r'Chaque alvéole entourée partage ses $\res6$ côtés, un avec chaque voisine : aucune paroi n’est construite en double, la cire est $\res{\text{économisée}}$. Le pavage ne laisse aucun trou.','Observer une alvéole entourée de six autres.','assert 6==6',figure='tri-14'),
E('Qui est qui ?',r'Vrai ou faux : « Tout carré est un losange » ; « Tout losange est un carré » ; « Tout rectangle a ses côtés opposés parallèles ». Justifier chaque réponse.',r'« Tout carré est un losange » : $\res{\text{vrai}}$, quatre côtés égaux. « Tout losange est un carré » : $\res{\text{faux}}$, il peut manquer les angles droits. « Tout rectangle a ses côtés opposés parallèles » : $\res{\text{vrai}}$, c’est une propriété du rectangle.','Passer chaque figure au crible des définitions.','assert 1==1',figure='tri-15')
],reperes=['Triangles et constructions','Rectangles, losanges, trapèzes','Pentagones et hexagones','Justifier aux instruments'],deco='geometrie')
